// spec: specs/contact-login-return.md (2.1) · кейс: .qa/tests/contact-login-return/CONTACT-AUTH-06.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение (запись заблокирована); в попапе ничего не нажимается.
import { test, expect } from '@playwright/test';
import { prepareGuest, loginPopup, LISTING_URL, LOAD } from './contact-popup.helpers';

test.use({ serviceWorkers: 'block' });

const POPUP_TEXT = 'הצטרפו לאתר ותוכלו להתעניין בעסקים, לנהל את תהליך חיפוש העסק שלכם באזור האישי בצורה נוחה ויעילה';

const SOURCES = [
  { name: 'объявление, «הצג מספר טלפון»', url: LISTING_URL, button: (p: import('@playwright/test').Page) => p.getByRole('button', { name: 'הצג מספר טלפון' }).first() },
  { name: 'объявление, «WhatsApp»', url: LISTING_URL, button: (p: import('@playwright/test').Page) => p.locator('button').filter({ hasText: /^\s*WhatsApp\s*$/ }).first() },
  { name: 'выдача /search, «הצגת טלפון»', url: '/search', button: (p: import('@playwright/test').Page) => p.getByRole('button', { name: 'הצגת טלפון' }).first() },
];

test.describe('Текст попапа входа у гостя', () => {
  for (const src of SOURCES) {
    test(`Попап входа (${src.name}): текст «…להתעניין בעסקים, לנהל…» посимвольно #565d74 @android @prod-safe`, async ({ page }) => {
      // каждый тест — новое окно: попап показывается раз за вкладку (b4s_guest_contact_prompt_shown)
      await prepareGuest(page);
      await page.goto(src.url);

      const btn = src.button(page);
      await expect(btn).toBeVisible({ timeout: 30_000 });
      await btn.click();
      const popup = loginPopup(page);
      await expect(popup, 'открылся попап входа').toBeVisible(LOAD);

      await expect(popup.getByText(/הרשמה קלה, מהירה וחד.פעמית/), 'заголовок на месте').toBeVisible();
      await expect(popup.getByText(/^הצטרפו לאתר/), 'текст под заголовком — ровно как в «מה רצוי»').toHaveText(POPUP_TEXT);
      await expect(popup, 'старого текста «ותוכלו לנהל» нет').not.toContainText('ותוכלו לנהל');
      for (const name of [/SMS/, /Google/, 'המשך בלי הרשמה', 'Close']) {
        await expect(popup.getByRole('button', { name }), `кнопка ${name} на месте`).toBeVisible();
      }
    });
  }
});
